use num_bigint::{BigInt,BigUint,Sign};use num_traits::{One,Zero,ToPrimitive};use serde_json::json;use zopro_bn254::{FpConfig,FqConfig,FrConfig};
fn uint(w:[u64;4])->BigUint{BigUint::from_bytes_le(&w.into_iter().flat_map(u64::to_le_bytes).collect::<Vec<_>>())}
fn digits(n:&BigUint)->[u128;5]{core::array::from_fn(|j|((n>>(52*j))&BigUint::from((1u64<<52)-1)).to_u128().unwrap())}
fn integer(t:&[u128])->BigUint{t.iter().enumerate().map(|(j,x)|BigUint::from(*x)<<(52*j)).sum()}
fn run<C:FpConfig>(bits:usize)->serde_json::Value{
let p=uint(C::P);let r=BigUint::one()<<bits;let twice=&p*2u32;assert!(&p*4u32<r);let mut inverse=BigUint::one();for _ in 0..9{inverse=(&inverse*(&r+2u32-(&p*&inverse)%&r))%&r;}assert_eq!((&inverse*&p)%&r,BigUint::one());let neginv=&r-&inverse;let pd=digits(&p);let mask=(1u128<<52)-1;let mut maximum=0u128;let mut cases=0;let mut seed=0x434f4d504c454d45u64;
let mut next=||{let mut bytes=[0u8;64];for b in bytes.chunks_mut(8){seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;b.copy_from_slice(&seed.to_le_bytes());}BigUint::from_bytes_le(&bytes)%(&twice+1u32)};
let edges=[BigUint::zero(),BigUint::one(),&p-1u32,p.clone(),&p+1u32,&twice-1u32,twice.clone()];let mut inputs=vec![];for i in 0..2401{inputs.push(core::array::from_fn::<_,4,_>(|j|edges[(i/7usize.pow(j as u32))%7].clone()));}for _ in 0..4096{inputs.push(core::array::from_fn(|_|next()));}
let mut chain:[BigUint;4]=core::array::from_fn(|_|next());
for i in 0..(inputs.len()+1024){let a=if i<inputs.len(){inputs[i].clone()}else{chain.clone()};let ad=a.each_ref().map(|x|digits(x));let complement=&r-1u32-&a[2];let nd=digits(&complement);assert_eq!(nd,core::array::from_fn(|j|ad[2][j]^(if j==4&&bits==256{(1u128<<48)-1}else{mask})));let x=&a[0]*&a[1]+&complement*&a[3]+&a[3];let q=(&x*&neginv)%&r;let exact=(&x+&q*&p)>>bits;assert!(exact<&p*4u32);
let z=BigInt::from_biguint(Sign::Plus,&a[0]*&a[1])-BigInt::from_biguint(Sign::Plus,&a[2]*&a[3]);let rr=BigInt::from_biguint(Sign::Plus,r.clone());let signed_mod=((&z%&rr)+&rr)%&rr;let q_signed=(signed_mod.to_biguint().unwrap()*&neginv)%&r;assert_eq!(q,q_signed);
let mut t=[ad[3][0],ad[3][1],ad[3][2],ad[3][3],ad[3][4],0];let mut observed_q=BigUint::zero();
for row in 0..5{for j in 0..5{for product in[ad[0][j]*ad[1][row],nd[j]*ad[3][row]]{t[j]+=product&mask;t[j+1]+=product>>52;}}
let width=if row==4&&bits==256{48}else{52};let lowmask=(1u128<<width)-1;let m=((t[0]&mask)*(C::INV as u128&mask))&lowmask;observed_q+=BigUint::from(m)<<(row*52);let low=((t[0]+lowmask)>>width)+(((m<<(52-width))*pd[0])>>52);
for j in 1..5{let product=m*pd[j];t[j]+=product&mask;t[j+1]+=product>>52;}maximum=maximum.max(*t.iter().max().unwrap());assert!(t.iter().all(|v|*v<(1u128<<61)));if width==52{t[1]+=low;t=[t[1],t[2],t[3],t[4],t[5],0];}else{t=[low+((t[1]&lowmask)<<4),(t[1]>>48)+((t[2]&lowmask)<<4),(t[2]>>48)+((t[3]&lowmask)<<4),(t[3]>>48)+((t[4]&lowmask)<<4),(t[4]>>48)+(t[5]<<4),0];}}
assert_eq!(q,observed_q);assert_eq!(integer(&t[..5]),exact);let u=BigInt::from_biguint(Sign::Plus,exact.clone())+BigInt::from_biguint(Sign::Plus,p.clone())-BigInt::from_biguint(Sign::Plus,a[3].clone());assert!(u>BigInt::zero()&&u<BigInt::from_biguint(Sign::Plus,&p*3u32));let mut carry=0i128;let mut out=[0u128;5];for j in 0..5{let v=t[j]as i128+pd[j]as i128-ad[3][j]as i128+carry;assert!(v>-(1i128<<62)&&v<(1i128<<62));carry=v>>52;out[j]=(v&mask as i128)as u128;}assert_eq!(carry,0);let out=integer(&out);assert_eq!(BigInt::from_biguint(Sign::Plus,out.clone()),u);let result=if out>=twice{out-&twice}else{out};assert!(result<twice);let expected=(((&z+BigInt::from_biguint(Sign::Plus,q*&p))>>bits)+BigInt::from_biguint(Sign::Plus,p.clone())).to_biguint().unwrap();assert_eq!(&result%&p,expected%&p);chain[0]=result;cases+=1;
}
json!({"bits":bits,"cases":cases,"exact_unsigned_CIOS_and_signed_quotient":true,"all_coefficient_bound":maximum.to_string(),"inclusive2p":true})}
fn main(){let rows=[run::<FqConfig>(256),run::<FqConfig>(260),run::<FrConfig>(256),run::<FrConfig>(260)];let n:u64=rows.iter().map(|v|v["cases"].as_u64().unwrap()).sum();let v=json!({"status":"passed","new_exact_REDC_cases":n,"rows":rows,"SDK_requests":0});std::fs::write("/home/ubuntu/src/zopro-perf-work/complement-difference175/model.json",serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("Model passed {n} exact CIOS/quotient/packing/correction cases");}
